16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: '+' followed by 8 to 15 digits")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
67	    private Set<Pet> pets;
68	
69	    /**
70	     * Default the registration date to the server's current date when none was
71	     * supplied. Runs only on insert, so an explicitly provided date is kept.
72	     */
73	    @PrePersist
74	    private void defaultRegistrationDate() {
75	        if (this.registrationDate == null) {
76	            this.registrationDate = LocalDate.now();
77	        }
78	    }
79	
80	    public String getAddress() {
81	        return this.address;
82	    }
83	
84	    public void setAddress(String address) {
85	        this.address = address;
86	    }
87	
88	    public String getCity() {
89	        return this.city;
90	    }
91	
92	    public void setCity(String city) {
93	        this.city = city;
94	    }
95	
96	    public String getTelephone() {
97	        return this.telephone;
98	    }
99	
100	    public void setTelephone(String telephone) {
101	        this.telephone = telephone;
102	    }
103	
104	    public String getEmail() {
105	        return this.email;
106	    }
107	
108	    public void setEmail(String email) {
109	        this.email = email;
110	    }
111	
112	    public LocalDate getRegistrationDate() {
113	        return this.registrationDate;
114	    }
115	
116	    public void setRegistrationDate(LocalDate registrationDate) {
117	        this.registrationDate = registrationDate;
118	    }
119	
120	    public String getCustomerCode() {
121	        return this.customerCode;
122	    }
123	
124	    public void setCustomerCode(String customerCode) {
125	        this.customerCode = customerCode;
126	    }
127	
128	    public String getHouseholdId() {
129	        return this.householdId;
130	    }
131	
132	    public void setHouseholdId(String householdId) {
133	        this.householdId = householdId;
134	    }
135	
136	    public Integer getNamesakeCount() {
137	        return this.namesakeCount;
138	    }
139	
140	    public void setNamesakeCount(Integer namesakeCount) {
141	        this.namesakeCount = namesakeCount;
142	    }
143	
144	    /**
145	     * Return this owner's name formatted as {@code LastName, FirstName}.
146	     */
147	    @Transient
148	    public String getDisplayName() {
149	        return this.getLastName() + ", " + this.getFirstName();
150	    }
151	
152	    protected Set<Pet> getPetsInternal() {
153	        if (this.pets == null) {
154	            this.pets = new HashSet<>();
155	        }
156	        return this.pets;
157	    }
158	
159	    protected void setPetsInternal(Set<Pet> pets) {
160	        this.pets = pets;
161	    }
162	
163	    public List<Pet> getPets() {
164	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
165	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
166	        return Collections.unmodifiableList(sortedPets);
167	    }
168	
169	    public void setPets(List<Pet> pets) {
170	        this.pets = new HashSet<>(pets);
171	    }
172	
173	    public void addPet(Pet pet) {
174	        getPetsInternal().add(pet);
175	        pet.setOwner(this);
176	    }
177	
178	    /**
179	     * Return the Pet with the given name, or null if none found for this Owner.
180	     *
181	     * @param name to test
182	     * @return true if pet name is already in use
183	     */
184	    public Pet getPet(String name) {
185	        return getPet(name, false);
186	    }
187	
188	    /**
189	     * Return the Pet with the given name, or null if none found for this Owner.
190	     *
191	     * @param name to test
192	     * @return true if pet name is already in use
193	     */
194	    public Pet getPet(String name, boolean ignoreNew) {
195	        name = name.toLowerCase();
196	        for (Pet pet : getPetsInternal()) {
197	            if (!ignoreNew || !pet.isNew()) {
198	                String compName = pet.getName();
199	                compName = compName.toLowerCase();
200	                if (compName.equals(name)) {
201	                    return pet;
202	                }
203	            }
204	        }
205	        return null;
206	    }
207	
208	    public Pet getPet(Integer petId) {
209	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
210	    }
211	
212	    @Override
213	    public String toString() {
214	        return new ToStringCreator(this)
215	
216	            .append("id", this.getId())
217	            .append("new", this.isNew())
218	            .append("lastName", this.getLastName())
219	            .append("firstName", this.getFirstName())
220	            .append("address", this.address)
221	            .append("city", this.city)
222	            .append("telephone", this.telephone)
223	            .append("email", this.email)
224	            .toString();
225	    }
226	}
