81	    public OwnerRestControllerV1(ClinicService clinicService,
82	                                 OwnerMapper ownerMapper,
83	                                 PetMapper petMapper,
84	                                 VisitMapper visitMapper,
85	                                 OwnerTelephoneUniquenessValidator telephoneUniquenessValidator,
86	                                 OwnerHouseholdUniquenessValidator householdUniquenessValidator,
87	                                 OwnerHouseholdRegistrar householdRegistrar,
88	                                 NamesakeCounter namesakeCounter) {
89	        this.clinicService = clinicService;
90	        this.ownerMapper = ownerMapper;
91	        this.petMapper = petMapper;
92	        this.visitMapper = visitMapper;
93	        this.telephoneUniquenessValidator = telephoneUniquenessValidator;
94	        this.householdUniquenessValidator = householdUniquenessValidator;
95	        this.householdRegistrar = householdRegistrar;
96	        this.namesakeCounter = namesakeCounter;
97	    }
