158	
159	    protected void setPetsInternal(Set<Pet> pets) {
160	        this.pets = pets;
161	    }
162	
163	    public List<Pet> getPets() {
164	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
165	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
166	        return Collections.unmodifiableList(sortedPets);
167	    }
